def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]

    for color in range(10):
        if color == bg:
            continue

        # Prefix sums for this color.
        p = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            for c in range(w):
                p[r + 1][c + 1] = (
                    p[r][c + 1] + p[r + 1][c] - p[r][c]
                    + (grid[r][c] == color)
                )

        cover = [[0] * (w + 1) for _ in range(h + 1)]
        for r0 in range(h):
            for r1 in range(r0 + 2, h + 1):
                for c0 in range(w):
                    for c1 in range(c0 + 2, w + 1):
                        area = (r1 - r0) * (c1 - c0)
                        count = p[r1][c1] - p[r0][c1] - p[r1][c0] + p[r0][c0]
                        if count * 4 >= area * 3:
                            cover[r0][c0] += 1
                            cover[r1][c0] -= 1
                            cover[r0][c1] -= 1
                            cover[r1][c1] += 1

        for r in range(h):
            running = 0
            for c in range(w):
                running += cover[r][c]
                if running:
                    out[r][c] = color

    return out
